-- UrgenceScan v2 — à exécuter dans le projet Supabase détenu par le cabinet.
create extension if not exists pgcrypto with schema extensions;
create table public.us_cabinets(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 100), owner_id uuid not null references auth.users(id), inventory jsonb not null default '[]'::jsonb check(jsonb_typeof(inventory)='array' and jsonb_array_length(inventory)<=2000), revision integer not null default 0, updated_at timestamptz not null default now());
create table public.us_members(cabinet_id uuid references public.us_cabinets on delete cascade, user_id uuid references auth.users on delete cascade, email text not null, display_name text not null, profession text not null default 'Médecin', role text not null check(role in ('owner','admin','editor','viewer')), primary key(cabinet_id,user_id));
create table public.us_invites(id uuid primary key default gen_random_uuid(),cabinet_id uuid not null references public.us_cabinets on delete cascade, email text not null,display_name text not null,profession text not null,role text not null check(role in ('admin','editor','viewer')),token_hash text unique not null,expires_at timestamptz not null default now()+interval '7 days',used_at timestamptz,created_at timestamptz not null default now());
create table public.us_backups(id uuid primary key default gen_random_uuid(),cabinet_id uuid not null references public.us_cabinets on delete cascade,inventory jsonb not null,revision integer not null,created_at timestamptz not null default now());
create table public.us_alert_settings(user_id uuid not null references auth.users on delete cascade,cabinet_id uuid not null references public.us_cabinets on delete cascade,enabled boolean not null default false, email_enabled boolean not null default false, telegram_enabled boolean not null default false, telegram_chat_id text not null default '', hour integer not null default 8 check(hour between 0 and 23), timezone text not null default 'Europe/Paris', frequency text not null default 'daily' check(frequency in ('daily','weekly')),weekday integer not null default 1 check(weekday between 0 and 6),use_product_threshold boolean not null default true,lookahead integer not null default 90 check(lookahead between 0 and 3650),include_expired boolean not null default true, primary key(user_id,cabinet_id));
create table public.us_deliveries(id text primary key,user_id uuid not null references auth.users on delete cascade,cabinet_id uuid not null references public.us_cabinets on delete cascade,channel text not null,status text not null default 'pending',attempts integer not null default 1,updated_at timestamptz not null default now(),error text);
create index on public.us_members(user_id);create index on public.us_backups(cabinet_id,created_at desc);create index on public.us_invites(cabinet_id);
-- Helpers non exposés : une fonction security definer ne doit jamais dépendre du search_path utilisateur.
create schema if not exists us_private;
revoke all on schema us_private from public,anon,authenticated;
grant usage on schema us_private to authenticated;
create function us_private.member_role(c uuid) returns text language sql stable security definer set search_path='' as $$select role from public.us_members where cabinet_id=c and user_id=(select auth.uid())$$;
revoke all on function us_private.member_role(uuid) from public;grant execute on function us_private.member_role(uuid) to authenticated;
alter table public.us_cabinets enable row level security;alter table public.us_members enable row level security;alter table public.us_invites enable row level security;alter table public.us_backups enable row level security;alter table public.us_alert_settings enable row level security;alter table public.us_deliveries enable row level security;
revoke all on public.us_cabinets,public.us_members,public.us_invites,public.us_backups,public.us_alert_settings,public.us_deliveries from anon,authenticated;
grant select on public.us_cabinets,public.us_members,public.us_invites,public.us_backups,public.us_deliveries to authenticated;
grant select,insert,update on public.us_alert_settings to authenticated;
grant all on public.us_cabinets,public.us_members,public.us_invites,public.us_backups,public.us_alert_settings,public.us_deliveries to service_role;
create policy cabinet_read on public.us_cabinets for select to authenticated using(us_private.member_role(id) is not null);
create policy members_read on public.us_members for select to authenticated using(us_private.member_role(cabinet_id) is not null);
create policy invites_read on public.us_invites for select to authenticated using(us_private.member_role(cabinet_id) in ('owner','admin'));
create policy backups_read on public.us_backups for select to authenticated using(us_private.member_role(cabinet_id) in ('owner','admin'));
create policy deliveries_read on public.us_deliveries for select to authenticated using(user_id=(select auth.uid()) and us_private.member_role(cabinet_id) is not null);
create policy settings_own on public.us_alert_settings for all to authenticated using(user_id=(select auth.uid()) and us_private.member_role(cabinet_id) is not null) with check(user_id=(select auth.uid()) and us_private.member_role(cabinet_id) is not null);
create function public.us_create_cabinet(p_name text) returns uuid language plpgsql security definer set search_path='' as $$declare c uuid;u auth.users;begin select * into u from auth.users where id=auth.uid();if u.id is null or u.email_confirmed_at is null then raise exception 'Vérifiez votre adresse e-mail avant de créer une trousse.';end if;insert into public.us_cabinets(name,owner_id) values(trim(p_name),u.id) returning id into c;insert into public.us_members values(c,u.id,u.email,coalesce(nullif(u.raw_user_meta_data->>'name',''),u.email),'Médecin','owner');return c;end$$;
create function public.us_save_inventory(p_cabinet uuid,p_revision integer,p_inventory jsonb) returns integer language plpgsql security definer set search_path='' as $$declare r integer;begin if us_private.member_role(p_cabinet) not in ('owner','admin','editor') or us_private.member_role(p_cabinet) is null then raise exception 'Droits insuffisants.';end if;if jsonb_typeof(p_inventory)<>'array' or jsonb_array_length(p_inventory)>2000 or octet_length(p_inventory::text)>20000000 then raise exception 'Inventaire trop volumineux ou invalide.';end if;if exists(select 1 from jsonb_array_elements(p_inventory) i where jsonb_typeof(i)<>'object' or coalesce(i->>'name','')='' or length(i->>'name')>150 or coalesce(i->>'expiry','') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(i->>'alertDays','90') !~ '^[0-9]{1,4}$') then raise exception 'Un produit contient des champs invalides.';end if;update public.us_cabinets set inventory=p_inventory,revision=revision+1,updated_at=now() where id=p_cabinet and revision=p_revision returning revision into r;if r is null then raise exception 'CONFLICT: la trousse a changé. Exportez vos changements puis actualisez.';end if;insert into public.us_backups(cabinet_id,inventory,revision) values(p_cabinet,p_inventory,r);delete from public.us_backups where cabinet_id=p_cabinet and id not in (select id from public.us_backups where cabinet_id=p_cabinet order by created_at desc limit 30);return r;end$$;
create function public.us_create_invite(p_cabinet uuid,p_email text,p_name text,p_profession text,p_role text) returns text language plpgsql security definer set search_path='' as $$declare t text; r text;begin r:=us_private.member_role(p_cabinet);if r is null or r not in ('owner','admin') or (p_role='admin' and r<>'owner') then raise exception 'Droits insuffisants.';end if;if p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(p_name)>150 or length(p_profession)>80 then raise exception 'Coordonnées invalides.';end if;t:=upper(encode(extensions.gen_random_bytes(20),'hex'));insert into public.us_invites(cabinet_id,email,display_name,profession,role,token_hash) values(p_cabinet,lower(trim(p_email)),trim(p_name),p_profession,p_role,encode(extensions.digest(t,'sha256'),'hex'));return t;end$$;
create function public.us_redeem_invite(p_token text) returns uuid language plpgsql security definer set search_path='' as $$declare i public.us_invites;u auth.users;begin select * into u from auth.users where id=auth.uid();if u.id is null or u.email_confirmed_at is null then raise exception 'Connexion et adresse e-mail vérifiée requises.';end if;select * into i from public.us_invites where token_hash=encode(extensions.digest(upper(trim(p_token)),'sha256'),'hex') and used_at is null and expires_at>now() for update;if i.id is null or lower(u.email)<>i.email then raise exception 'Code invalide, expiré ou associé à une autre adresse.';end if;insert into public.us_members values(i.cabinet_id,u.id,u.email,i.display_name,i.profession,i.role) on conflict(cabinet_id,user_id) do nothing;update public.us_invites set used_at=now() where id=i.id;return i.cabinet_id;end$$;
create function public.us_revoke_invite(p_id uuid) returns void language plpgsql security definer set search_path='' as $$declare c uuid;begin select cabinet_id into c from public.us_invites where id=p_id;if us_private.member_role(c) not in ('owner','admin') or us_private.member_role(c) is null then raise exception 'Droits insuffisants.';end if;delete from public.us_invites where id=p_id;end$$;
create function public.us_remove_member(p_cabinet uuid,p_user uuid) returns void language plpgsql security definer set search_path='' as $$declare r text;target text;begin r:=us_private.member_role(p_cabinet);select role into target from public.us_members where cabinet_id=p_cabinet and user_id=p_user;if r is null or r not in ('owner','admin') or target='owner' or (target='admin' and r<>'owner') or p_user=auth.uid() then raise exception 'Droits insuffisants.';end if;delete from public.us_members where cabinet_id=p_cabinet and user_id=p_user;delete from public.us_alert_settings where cabinet_id=p_cabinet and user_id=p_user;end$$;
create function public.us_reserve_delivery(p_id text,p_user uuid,p_cabinet uuid,p_channel text) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin insert into public.us_deliveries(id,user_id,cabinet_id,channel) values(p_id,p_user,p_cabinet,p_channel) on conflict(id) do update set status='pending',updated_at=now(),attempts=public.us_deliveries.attempts+1 where public.us_deliveries.status in ('failed','pending') and public.us_deliveries.updated_at<now()-interval '15 minutes' and public.us_deliveries.attempts<4;get diagnostics n=row_count;return n>0;end$$;
revoke all on function public.us_create_cabinet(text),public.us_save_inventory(uuid,integer,jsonb),public.us_create_invite(uuid,text,text,text,text),public.us_redeem_invite(text),public.us_revoke_invite(uuid),public.us_remove_member(uuid,uuid),public.us_reserve_delivery(text,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.us_create_cabinet(text),public.us_save_inventory(uuid,integer,jsonb),public.us_create_invite(uuid,text,text,text,text),public.us_redeem_invite(text),public.us_revoke_invite(uuid),public.us_remove_member(uuid,uuid) to authenticated;
grant execute on function public.us_reserve_delivery(text,uuid,uuid,text) to service_role;
